const S = require('/files/bot_state_v2.js');
const input = $input.first().json;

const raw_msg_id = String(input.msg_id || '').trim();
const attachmentIndex = input.attachment_index == null ? 0 : Number(input.attachment_index);
if (!Number.isInteger(attachmentIndex) || attachmentIndex < 0) return [{json:{error:'attachment_index_invalid'}}];
const reason = String(input.reason || '').trim();
const msg_id = raw_msg_id.replace(/^msg_/, '');

if (!msg_id) {
  return [{ json: { error: 'msg_id_required', received: raw_msg_id } }];
}

// Find contactKey + media via ct:* scan
const result = await S.run(async r => {
  const keys = [];
  let cursor = '0';
  do {
    const [nc, batch] = await r.scan(cursor, 'MATCH', 'ct:*', 'COUNT', 100);
    cursor = nc;
    keys.push(...batch);
  } while (cursor !== '0');

  for (const fullKey of keys) {
    const raw = await r.get(fullKey);
    if (!raw) continue;
    try {
      const st = JSON.parse(raw);
      const arr = (st.media && st.media.urls) || [];
      const matches = arr.filter(m => String(m.msgId) === msg_id);
      if (matches.length) return { contactKey: fullKey.replace(/^ct:/, ''), media: matches[attachmentIndex], attachmentCount: matches.length };
    } catch(e) {}
  }
  return null;
});

if (!result) {
  return [{ json: { error: 'media_not_found', msg_id } }];
}

const { contactKey, media, attachmentCount } = result;
if (!media) return [{json:{error:'attachment_index_out_of_range',msg_id,attachmentIndex,attachmentCount}}];

// Rate limit (20/contact/hour)
const rlKey = 'rate:analyze:' + contactKey;
const rlCount = await S.run(r => r.incr(rlKey));
if (rlCount === 1) await S.run(r => r.expire(rlKey, 3600));
if (rlCount > 20) {
  return [{ json: { error: 'rate_limit_exceeded', count: rlCount, contactKey } }];
}

// Cache check
const cacheKey = 'analysis:media:' + msg_id + ':' + attachmentIndex;
const cached = await S.run(r => r.get(cacheKey));
if (cached) {
  try {
    return [{ json: { cached: true, analysis: JSON.parse(cached), contactKey, msg_id, reason, attachmentIndex, attachmentCount } }];
  } catch(e) {}
}

return [{
  json: {
    msg_id,
    attachmentIndex,
    attachmentCount,
    reason,
    contactKey,
    url: media.url,
    media_type: media.type,
    media_name: media.name
  }
}];

const S = require('/files/bot_state_v2.js');
const prep = $('Capture Audit').first().json.prep;
const input = $('Capture Audit').first().json.input;

// ─────────────────────────────────────────────────────────
// Helper: map analysis output to media type
// ─────────────────────────────────────────────────────────
function detectedType(analysis) {
  if (!analysis) return 'file';
  if (analysis.from_video) return 'video';
  if (analysis.from_image) return 'image';
  if (analysis.from_pdf) return 'pdf';
  if (analysis.from_doc) return 'doc';
  if (analysis.from_text) return 'text';
  if (analysis.from_archive) return 'archive';
  if (analysis.from_link) return 'link';
  if (['image','photo','design','screenshot'].includes(analysis.type)) return 'image';
  if (analysis.type === 'document') return 'doc';
  return 'file';
}

// ── Cache hit path ──
if (prep.cached) {
  const analysis = prep.analysis;
  if (!analysis || analysis.error || analysis.ok === false) return [{json:{error:'invalid_cached_analysis',msg_id:prep.msg_id}}];
  if (prep.contactKey && analysis) {
    await S.run(r => S.update(r, prep.contactKey, st => {
      const arr = (st.media && st.media.urls) || [];
      const matches = arr.filter(m => String(m.msgId) === prep.msg_id);
      const target = matches[prep.attachmentIndex || 0];
      const i = target ? arr.indexOf(target) : -1;
      if (i >= 0 && !arr[i].analyzed) {
        arr[i].analyzed = analysis;
        arr[i].analyzedAt = Date.now();
        arr[i].analyzedReason = prep.reason || 'cache_heal';
        // Refine the media type based on actual analysis
        arr[i].type = detectedType(analysis);
        if (analysis.pages)  arr[i].pages  = analysis.pages;
        if (analysis.slides) arr[i].slides = analysis.slides;
        if (analysis.sheets) arr[i].sheets = analysis.sheets;
      }
      if (st.pendingInternalMedia) {
        const internalPending = arr.filter(m => m.source === 'internal_note' && !m.analyzed).length;
        if (internalPending === 0) st.pendingInternalMedia = false;
      }
      return st;
    }));
  }
  return [{ json: analysis }];
}

// ── Error paths ──
if (prep.error) return [{ json: prep }];
if (input.error) {
  return [{ json: { error: input.error, detail: input.detail || null, contactKey: prep.contactKey, msg_id: prep.msg_id } }];
}
if (!input.success) {
  return [{ json: { error: input.error || 'analyzer_failed', contactKey: prep.contactKey, msg_id: prep.msg_id } }];
}

const analysis = input.analysis;
if (!analysis || typeof analysis !== 'object' || Array.isArray(analysis) || analysis.error || analysis.ok === false) {
  return [{ json: { error: 'no_analysis_from_service', contactKey: prep.contactKey, msg_id: prep.msg_id } }];
}

// ── Cache ──
const cacheKey = 'analysis:media:' + prep.msg_id + ':' + (prep.attachmentIndex || 0);
await S.run(r => r.set(cacheKey, JSON.stringify(analysis), 'EX', 86400));

// ── Write back to state ──
if (prep.contactKey) {
  await S.run(r => S.update(r, prep.contactKey, st => {
    const arr = (st.media && st.media.urls) || [];
    const matches = arr.filter(m => String(m.msgId) === prep.msg_id);
      const target = matches[prep.attachmentIndex || 0];
      const i = target ? arr.indexOf(target) : -1;
    if (i >= 0) {
      arr[i].analyzed = analysis;
      arr[i].analyzedAt = Date.now();
      arr[i].analyzedReason = prep.reason;
      // Refine the media type based on actual analysis
      arr[i].type = detectedType(analysis);
      if (analysis.pages)  arr[i].pages  = analysis.pages;
      if (analysis.slides) arr[i].slides = analysis.slides;
      if (analysis.sheets) arr[i].sheets = analysis.sheets;
    }
    if (st.pendingInternalMedia) {
      const internalPending = arr.filter(m => m.source === 'internal_note' && !m.analyzed).length;
      if (internalPending === 0) st.pendingInternalMedia = false;
    }
    return st;
  }));
}

// ── Log event ──
if (prep.contactKey) {
  await S.run(r => S.logEvent(r, prep.contactKey, 'media_analyzed', {
    msg_id: prep.msg_id,
    type: analysis.type,
    pages: analysis.pages || null,
    reason: prep.reason
  }));
}

return [{ json: analysis }];

let prep = $('Prepare Media').first().json;
let input = $input.first().json;
try {
  const { captureAudit } = require('/files/audit-media/audit-media.cjs');
  const { writeEvidence } = require('/files/audit-media/production-store.cjs');
  const analysis = prep.cached ? prep.analysis : input.analysis;
  if (analysis && !prep.error && (prep.cached || input.success)) {
    const captured = await captureAudit({ analysis, accountId: 2, messageId: prep.msg_id,
      attachmentIndex: prep.attachmentIndex || 0,
      write: record => writeEvidence(record, '/files/audit-media/data/evidence.sqlite') });
    if (prep.cached) prep = { ...prep, analysis: captured.analysis };
    else input = { ...input, analysis: captured.analysis };
    if (!captured.stored) console.log('[audit] evidence not stored: ' + captured.reason);
  }
} catch (_) {
  // Strip reserved fields even when the module cannot load; no customer error.
  const strip = v => Array.isArray(v) ? v.map(strip) : v && typeof v === 'object'
    ? Object.fromEntries(Object.entries(v).filter(([k])=>k!=='_audit').map(([k,x])=>[k,strip(x)])) : v;
  prep = strip(prep); input = strip(input);
  console.log('[audit] capture unavailable');
}
return [{json:{prep,input}}];
